export const GLOSSARY_SHARD = Object.freeze({"market-capitalization":{"slug":"market-capitalization","cat":"basics","en":"Market capitalization","contentLocale":"vi","term":"Vốn hóa thị trường (Market cap)","aka":["vốn hóa","market cap","mcap"],"short":"Vốn hóa thị trường (market cap) của một đồng tiền mã hóa là giá hiện tại nhân với nguồn cung lưu hành, cho biết tổng giá trị thị trường đang định cho lượng coin đang lưu thông.","body":[["Công thức đơn giản: vốn hóa = giá × ",["nguồn cung lưu hành","circulating-supply"],". Các trang dữ liệu như CoinGecko hay CoinMarketCap dùng con số này để xếp hạng coin. Vốn hóa giúp bạn so sánh quy mô các dự án tốt hơn nhiều so với chỉ nhìn giá một đồng."],["Một coin giá 0,05 ",["USDT","usdt"]," chưa chắc đã rẻ: nếu nó có hàng trăm tỷ đồng lưu hành, vốn hóa có thể còn lớn hơn một coin giá 50 USDT. Muốn giá tăng gấp đôi thì vốn hóa cũng phải tăng gấp đôi, điều càng khó khi dự án đã lớn."],["Vốn hóa không phải là lượng tiền thật đã đổ vào dự án, và cũng không cho biết bạn bán được bao nhiêu mà không làm giá giảm. Hãy xem thêm ",["khối lượng giao dịch","trading-volume"],", độ sâu ",["sổ lệnh","order-book"]," và ",["định giá pha loãng hoàn toàn (FDV)","fully-diluted-valuation"]," để có bức tranh đầy đủ."]],"example":"Coin A giá 2 USDT với 500 triệu đồng lưu hành, vốn hóa là 1 tỷ USDT. Coin B giá 0,01 USDT với 200 tỷ đồng lưu hành, vốn hóa là 2 tỷ USDT. Dù giá B thấp hơn A 200 lần, B lại lớn gấp đôi A về vốn hóa. Muốn B lên 1 USDT, vốn hóa của nó phải đạt 200 tỷ USDT, một con số khó xảy ra với phần lớn dự án.","mistakes":["So sánh coin chỉ dựa vào giá một đồng mà bỏ qua nguồn cung.","Nghĩ rằng vốn hóa 1 tỷ USDT nghĩa là có 1 tỷ USDT tiền mặt đã đầu tư vào dự án.","Chỉ nhìn vốn hóa mà quên kiểm tra lượng token sắp được mở khóa."],"faq":[{"q":"Vốn hóa thấp có phải là tốt không?","a":"Vốn hóa thấp có thể tăng theo phần trăm dễ hơn, nhưng thường đi kèm thanh khoản mỏng và rủi ro cao hơn. Đó không phải tín hiệu tốt hay xấu nếu đứng một mình."},{"q":"Vốn hóa khác FDV ở điểm nào?","a":"Vốn hóa dùng nguồn cung đang lưu hành, còn FDV dùng tổng cung tối đa. Khoảng cách lớn giữa hai con số cho thấy còn nhiều token chưa ra thị trường."}],"title":"Vốn hóa thị trường (market cap) là gì?","description":"Market cap là gì, cách tính vốn hóa coin, vì sao giá thấp không có nghĩa là rẻ và cần xem thêm chỉ số nào.","related":[["fully-diluted-valuation","Định giá pha loãng hoàn toàn (FDV)","Định giá pha loãng hoàn toàn (FDV) là giá hiện tại của token nhân với tổng cung tối đa, cho biết dự án sẽ được định giá bao nhiêu nếu toàn bộ token đã được phát hành."],["circulating-supply","Nguồn cung lưu hành (Circulating supply)","Nguồn cung lưu hành (circulating supply) là số lượng coin hoặc token đang thực sự có trên thị trường và có thể giao dịch, không tính phần bị khóa, chưa phát hành hoặc đã bị đốt."],["trading-volume","Khối lượng giao dịch (Volume)","Khối lượng giao dịch là tổng giá trị hoặc số lượng một tài sản đã được mua bán trong một khoảng thời gian, thường tính trong 24 giờ."],["tokenomics","Tokenomics (kinh tế học token)","Tokenomics là toàn bộ thiết kế kinh tế của một token: tổng cung, cách phân bổ, lịch mở khóa, cơ chế phát hành và đốt, cùng công dụng khiến người dùng cần giữ hoặc dùng token đó."],["altcoin","Altcoin","Altcoin là cách gọi chung mọi đồng tiền mã hóa không phải Bitcoin, từ các dự án lớn như Ethereum, Solana đến những token nhỏ mới niêm yết."]],"lesson":null,"coin":null,"tool":"/coins","cta":false},"market-maker":{"slug":"market-maker","cat":"trading","en":"Market maker","contentLocale":"vi","term":"Nhà tạo lập thị trường (Market maker)","aka":["market maker","MM","tạo lập thị trường"],"short":"Nhà tạo lập thị trường (market maker) là cá nhân hoặc tổ chức liên tục đặt lệnh mua và lệnh bán cho một tài sản để cung cấp thanh khoản và kiếm lời từ chênh lệch giá.","body":["Market maker đặt lệnh mua thấp hơn một chút và lệnh bán cao hơn một chút so với giá hiện tại. Khi cả hai phía đều được khớp, họ kiếm được phần chênh lệch spread. Nhờ đó, người giao dịch khác luôn có lệnh để khớp và spread được giữ hẹp.",["Nhiều ",["sàn tập trung","centralized-exchange"]," ký thỏa thuận với các công ty tạo lập thị trường chuyên nghiệp, thường kèm ưu đãi ",["phí maker","maker-taker-fees"]," thấp. Dự án mới ",["niêm yết token","token-listing"]," cũng hay thuê market maker để ",["sổ lệnh","order-book"]," không bị trống. Trên ",["DEX","dex"],", vai trò này được thay bằng ",["AMM","amm"]," và các nhà cung cấp thanh khoản."],"Market maker có rủi ro riêng: khi giá chạy mạnh một chiều, họ có thể bị tồn kho lỗ. Vì vậy trong lúc thị trường hoảng loạn, họ thường kéo lệnh ra xa hoặc rút bớt, làm thanh khoản mỏng đi."],"example":"Giả sử ETH đang giao dịch quanh 3.000 USDT. Một market maker đặt lệnh mua 10 ETH ở 2.999 và lệnh bán 10 ETH ở 3.001. Nếu cả hai lệnh khớp, họ mua 29.990 USDT và bán 30.010 USDT, lãi gộp 20 USDT trước phí. Lặp lại hàng nghìn lần mỗi ngày, khoản lãi nhỏ này trở thành nguồn thu chính, nhưng chỉ khi giá không chạy một chiều quá xa.","mistakes":["Nghĩ rằng market maker luôn thao túng giá, trong khi vai trò cơ bản của họ là cung cấp thanh khoản.","Cho rằng thanh khoản do market maker tạo ra sẽ luôn có mặt, kể cả lúc thị trường sập.","Nhầm market maker với maker trong phí maker/taker, vốn chỉ là vai trò của một lệnh."],"faq":[{"q":"Market maker kiếm tiền bằng cách nào?","a":"Chủ yếu từ chênh lệch giá mua-bán và ưu đãi phí từ sàn. Họ cần quản lý tồn kho để không lỗ khi giá biến động mạnh."},{"q":"Người dùng thường có thể làm market maker không?","a":"Bạn có thể đặt lệnh giới hạn chờ để đóng vai maker, hoặc cung cấp thanh khoản trên DEX. Tuy vậy, tạo lập thị trường chuyên nghiệp cần vốn và hệ thống tự động."}],"title":"Market maker là gì? Nhà tạo lập thị trường crypto","description":"Market maker là gì, họ kiếm tiền từ spread ra sao và vì sao thanh khoản do họ tạo có thể biến mất khi thị trường hoảng loạn.","related":[["liquidity","Thanh khoản (Liquidity)","Thanh khoản là mức độ dễ dàng mua hoặc bán một tài sản với số lượng lớn mà giá không bị đẩy đi nhiều."],["bid-ask-spread","Chênh lệch giá mua-bán (Spread)","Chênh lệch giá mua-bán (bid-ask spread) là khoảng cách giữa giá mua cao nhất (bid) và giá bán thấp nhất (ask) trong sổ lệnh, và là chi phí ngầm mỗi khi bạn mua rồi bán ngay bằng lệnh thị trường."],["maker-taker-fees","Phí maker và phí taker (Maker/Taker fee)","Phí maker và phí taker là hai mức phí giao dịch khác nhau: maker trả phí khi lệnh của bạn nằm chờ trên sổ lệnh và tạo thêm thanh khoản, taker trả phí khi lệnh của bạn khớp ngay với lệnh có sẵn."],["order-book","Sổ lệnh (Order book)","Sổ lệnh (order book) là danh sách theo thời gian thực của tất cả lệnh mua và lệnh bán đang chờ khớp cho một cặp giao dịch, sắp xếp theo mức giá và khối lượng."],["amm","Tạo lập thị trường tự động (AMM)","AMM (tạo lập thị trường tự động) là cơ chế của nhiều DEX dùng công thức toán học và pool thanh khoản để định giá và khớp giao dịch, thay cho sổ lệnh mua bán truyền thống."]],"lesson":null,"coin":null,"tool":null,"cta":false},"risk-reward-ratio":{"slug":"risk-reward-ratio","cat":"trading","en":"Risk-reward ratio","contentLocale":"vi","term":"Tỷ lệ rủi ro/lợi nhuận (Risk-reward ratio)","aka":["R:R","RR","risk reward","tỷ lệ R/R"],"short":"Tỷ lệ rủi ro/lợi nhuận (R:R) so sánh số tiền bạn có thể mất nếu chạm cắt lỗ với số tiền bạn có thể lãi nếu chạm chốt lời trong cùng một lệnh.","body":[["Bạn tính R:R trước khi vào lệnh: khoảng cách từ giá vào đến ",["cắt lỗ","stop-loss"]," là rủi ro, khoảng cách từ giá vào đến ",["chốt lời","take-profit"]," là lợi nhuận. Một lệnh rủi ro 100 để kiếm 300 có tỷ lệ 1:3."],"R:R phải đi cùng tỷ lệ thắng. Với tỷ lệ 1:3, bạn chỉ cần thắng hơn 25% số lệnh để hòa vốn trước phí. Với tỷ lệ 1:1, bạn cần thắng hơn 50%. Vì vậy một chiến lược R:R cao nhưng hiếm khi chạm chốt lời chưa chắc tốt hơn.",["Mục tiêu chốt lời cũng phải thực tế, ví dụ dựa trên ",["vùng kháng cự","support-and-resistance"]," gần nhất, không nên đặt xa chỉ để tỷ lệ trông đẹp. ",["Lệnh OCO","oco-order"]," giúp đặt cắt lỗ và chốt lời cùng lúc."]],"example":["Giả sử bạn mua BNB ở 600 ",["USDT","usdt"],", cắt lỗ ở 585 và chốt lời ở 645. Rủi ro là 15 USDT, lợi nhuận tiềm năng là 45 USDT, tỷ lệ R:R là 1:3. Nếu bạn thực hiện 10 lệnh tương tự với cùng khối lượng, thắng 3 lệnh và thua 7 lệnh, kết quả là 3 × 45 - 7 × 15 = 135 - 105 = 30 USDT mỗi đơn vị, vẫn dương trước phí."],"mistakes":["Dời cắt lỗ ra xa khi giá đi ngược, làm R:R thực tế xấu đi.","Đặt chốt lời quá xa so với cấu trúc giá chỉ để có tỷ lệ đẹp trên giấy.","Bỏ qua tỷ lệ thắng khi đánh giá một chiến lược."],"faq":[{"q":"Tỷ lệ R:R bao nhiêu là tốt?","a":"Nhiều người nhắm tối thiểu 1:2, nhưng không có con số đúng cho mọi người. Tỷ lệ tốt phải đi kèm tỷ lệ thắng đủ cao để có lãi sau phí."},{"q":"Cách tính risk reward ratio thế nào?","a":"Lấy khoảng cách từ giá vào đến chốt lời chia cho khoảng cách từ giá vào đến cắt lỗ. Ví dụ 30 chia 10 là tỷ lệ 1:3."}],"title":"Risk reward ratio là gì? Cách tính tỷ lệ R:R","description":"Tỷ lệ rủi ro/lợi nhuận (R:R) là gì, cách tính, và vì sao nó phải đi cùng tỷ lệ thắng để chiến lược có lãi.","related":[["position-sizing","Quản lý khối lượng vị thế (Position sizing)","Position sizing là cách xác định bạn nên mở một lệnh lớn bao nhiêu, dựa trên số tiền bạn chấp nhận mất nếu lệnh chạm cắt lỗ."],["stop-loss","Lệnh cắt lỗ (Stop-loss)","Lệnh cắt lỗ (stop-loss) là lệnh tự động đóng vị thế khi giá chạm một mức bạn đặt trước, nhằm giới hạn khoản lỗ trong trường hợp thị trường đi ngược kỳ vọng."],["take-profit","Lệnh chốt lời (Take-profit)","Lệnh chốt lời (take-profit) là lệnh tự động đóng toàn bộ hoặc một phần vị thế khi giá đạt mức lợi nhuận bạn đặt trước, giúp bạn khóa lãi mà không cần theo dõi màn hình liên tục."],["oco-order","Lệnh OCO (One-cancels-the-other)","Lệnh OCO (one-cancels-the-other) là cặp hai lệnh được đặt cùng lúc, thường một chốt lời và một cắt lỗ; khi một lệnh khớp hoặc kích hoạt, lệnh còn lại tự động bị hủy."]],"lesson":{"id":"E16","slug":"position-sizing-basics","ep":16,"title":"Xác định mức có thể mất trước khi quyết định mua bao nhiêu"},"coin":null,"tool":null,"cta":false},"futures-contract":{"slug":"futures-contract","cat":"derivatives","en":"Futures contract","contentLocale":"vi","term":"Hợp đồng tương lai (Futures)","aka":["futures","hợp đồng futures","phái sinh tương lai"],"short":"Hợp đồng tương lai là thỏa thuận mua hoặc bán một tài sản theo giá xác định, cho phép bạn kiếm lời từ biến động giá mà không cần sở hữu tài sản thật.","body":[["Trong crypto, hợp đồng tương lai cho phép bạn mở ",["vị thế long","long-and-short"]," (kỳ vọng giá tăng) hoặc short (kỳ vọng giá giảm) bằng ký quỹ và thường có ",["đòn bẩy","leverage"],". Bạn không nhận coin thật; lãi lỗ được tính bằng chênh lệch giá và thanh toán bằng ",["USDT","usdt"]," hoặc bằng chính coin đó."],["Có hai dạng chính: ",["hợp đồng tương lai vĩnh cửu (perpetual)","perpetual-futures"]," không có ngày hết hạn và dùng ",["funding rate","funding-rate"]," để bám giá spot, và hợp đồng giao sau có ngày đáo hạn cố định, ví dụ theo quý. Ngoài ra còn phân biệt ký quỹ bằng USDT hay ký quỹ bằng coin."],["Futures hữu ích để ",["phòng hộ","hedging"]," hoặc giao dịch hai chiều, nhưng đòn bẩy khiến khoản lỗ có thể vượt số ký quỹ của vị thế và dẫn tới thanh lý. Quy tắc ký quỹ, phí và giới hạn đòn bẩy khác nhau giữa các sàn, và một số quốc gia hạn chế sản phẩm này với nhà đầu tư cá nhân."]],"example":"Giả sử BTC đang ở 70.000 USDT và bạn mở long 0,1 BTC hợp đồng tương lai với đòn bẩy 10x. Giá trị vị thế là 7.000 USDT, ký quỹ ban đầu là 700 USDT. Nếu giá lên 73.500 USDT (tăng 5%), lãi là 0,1 × 3.500 = 350 USDT, tức 50% trên ký quỹ. Nếu giá giảm 5%, bạn lỗ 350 USDT, mất một nửa ký quỹ.","mistakes":["Nghĩ rằng giao dịch futures là mua coin thật, trong khi bạn chỉ nắm một hợp đồng.","Dùng đòn bẩy cao mà không biết giá thanh lý nằm ở đâu.","Không phân biệt hợp đồng vĩnh cửu với hợp đồng có ngày đáo hạn."],"faq":[{"q":"Futures khác spot thế nào?","a":"Spot là mua bán coin thật và nhận coin ngay. Futures là hợp đồng dựa trên giá coin, có thể long hoặc short và dùng đòn bẩy."},{"q":"Người mới có nên chơi futures?","a":"Bạn nên hiểu rõ ký quỹ, đòn bẩy và thanh lý trước, rồi bắt đầu với đòn bẩy thấp và vị thế nhỏ. Thua lỗ trong futures có thể đến rất nhanh."}],"title":"Hợp đồng tương lai (futures) là gì trong crypto?","description":"Hợp đồng tương lai crypto là gì, khác spot ra sao, các loại futures phổ biến và cách tính lãi lỗ khi dùng đòn bẩy.","related":[["perpetual-futures","Hợp đồng tương lai vĩnh cửu (Perpetual)","Hợp đồng tương lai vĩnh cửu (perpetual) là hợp đồng tương lai không có ngày đáo hạn, dùng cơ chế funding rate để giữ giá hợp đồng bám sát giá spot."],["delivery-futures","Hợp đồng tương lai giao sau (Delivery futures)","Hợp đồng tương lai giao sau là hợp đồng có ngày đáo hạn cố định, ví dụ theo tuần hoặc theo quý, và được tất toán theo giá chỉ số vào thời điểm đáo hạn."],["leverage","Đòn bẩy (Leverage)","Đòn bẩy là việc dùng một khoản ký quỹ nhỏ để mở vị thế có giá trị lớn hơn nhiều lần, làm phóng đại cả lợi nhuận lẫn thua lỗ."],["margin-trading","Giao dịch ký quỹ (Margin trading)","Giao dịch ký quỹ là việc vay thêm vốn từ sàn, dùng tài sản của bạn làm tài sản đảm bảo, để mở vị thế lớn hơn số tiền bạn có."],["hedging","Phòng hộ (Hedging)","Phòng hộ (hedging) là việc mở một vị thế ngược chiều để giảm rủi ro biến động giá của tài sản bạn đang nắm giữ, đổi lại bằng việc hạn chế phần lợi nhuận."]],"lesson":{"id":"E18","slug":"spot-vs-futures","ep":18,"title":"Giao ngay và tương lai: bạn không mua cùng một thứ"},"coin":null,"tool":"/topics/derivatives","cta":true},"cross-margin":{"slug":"cross-margin","cat":"derivatives","en":"Cross margin","contentLocale":"vi","term":"Ký quỹ chéo (Cross margin)","aka":["cross margin","cross","margin chéo"],"short":"Ký quỹ chéo là chế độ trong đó toàn bộ số dư khả dụng của tài khoản được dùng chung làm ký quỹ cho các vị thế, giúp hạn chế thanh lý sớm nhưng có thể khiến bạn mất cả tài khoản.","body":[["Ở chế độ chéo, khi một vị thế lỗ, sàn tự động dùng số dư còn lại trong tài khoản để giữ vị thế đó không ",["bị thanh lý","liquidation"],". Lãi chưa thực hiện của vị thế này cũng có thể hỗ trợ ký quỹ cho vị thế khác."],["Ưu điểm là vị thế có nhiều không gian chịu ",["biến động","volatility"]," hơn, phù hợp khi bạn giữ các vị thế ",["phòng hộ","hedging"]," lẫn nhau. Nhược điểm là nếu thị trường đi ngược mạnh, một vị thế thua lớn có thể kéo toàn bộ số dư xuống và khi thanh lý xảy ra, bạn mất phần lớn tài khoản."],["Ký quỹ chéo thường là chế độ mặc định trong ",["tài khoản hợp nhất","unified-trading-account"]," của nhiều sàn. Cách tính và phạm vi tài sản được tính vào ký quỹ khác nhau, nên bạn cần xem kỹ cài đặt của sàn."]],"example":["Giả sử tài khoản có 3.000 ",["USDT","usdt"]," và bạn mở long DOGE trị giá 3.000 USDT ở chế độ chéo. Vì cả 3.000 USDT đều làm ký quỹ, giá DOGE phải giảm gần 100% trừ ",["ký quỹ duy trì","maintenance-margin"]," mới bị thanh lý, thay vì khoảng 10% như khi bạn chỉ gán 300 USDT ký quỹ cô lập. Nhưng nếu bạn mở vị thế 30.000 USDT (10x trên toàn tài khoản), giá giảm khoảng 9-10% là bạn mất gần hết 3.000 USDT."],"mistakes":["Mở nhiều vị thế lớn ở chế độ chéo mà không theo dõi tổng rủi ro của tài khoản.","Nghĩ rằng ký quỹ chéo an toàn hơn trong mọi trường hợp.","Để số dư dự phòng trong tài khoản futures chéo mà quên rằng nó có thể bị dùng để cứu vị thế thua."],"faq":[{"q":"Ký quỹ chéo là gì?","a":"Là chế độ dùng toàn bộ số dư khả dụng làm ký quỹ chung cho các vị thế. Vị thế khó bị thanh lý hơn nhưng nếu bị thanh lý thì mất nhiều hơn."},{"q":"Cross margin có nguy hiểm không?","a":"Có thể, vì một vị thế thua lớn có thể xóa sạch số dư. Bạn nên giới hạn khối lượng vị thế và chỉ để lượng vốn bạn chấp nhận rủi ro trong tài khoản."}],"title":"Ký quỹ chéo (cross margin) là gì?","description":"Ký quỹ chéo là gì, cách số dư chung hỗ trợ các vị thế và vì sao một lệnh thua có thể kéo cả tài khoản bị thanh lý.","related":[["isolated-margin","Ký quỹ cô lập (Isolated margin)","Ký quỹ cô lập là chế độ trong đó mỗi vị thế có một khoản ký quỹ riêng, nên nếu bị thanh lý bạn chỉ mất phần ký quỹ đã gán cho vị thế đó."],["portfolio-margin","Ký quỹ danh mục (Portfolio margin)","Ký quỹ danh mục là chế độ tính ký quỹ dựa trên rủi ro tổng thể của cả danh mục, cho phép các vị thế phòng hộ lẫn nhau được giảm yêu cầu ký quỹ."],["unified-trading-account","Tài khoản giao dịch hợp nhất (UTA)","Tài khoản giao dịch hợp nhất là loại tài khoản gộp spot, ký quỹ, hợp đồng tương lai và quyền chọn vào một ví duy nhất, cho phép dùng chung tài sản làm ký quỹ."],["liquidation","Thanh lý (Liquidation)","Thanh lý (hay cháy tài khoản) là khi sàn tự động đóng vị thế có đòn bẩy của bạn vì ký quỹ không còn đủ đáp ứng mức ký quỹ duy trì."]],"lesson":{"id":"E22","slug":"cross-margin","ep":22,"title":"Ký quỹ chéo: vì sao một vị thế lỗ có thể ảnh hưởng đến các vị thế khác"},"coin":null,"tool":null,"cta":false},"long-and-short":{"slug":"long-and-short","cat":"derivatives","en":"Long and short positions","contentLocale":"vi","term":"Long và Short (Vị thế mua và bán)","aka":["long","short","vị thế long","vị thế short","đánh lên đánh xuống"],"short":"Long là mở vị thế kiếm lời khi giá tăng, short là mở vị thế kiếm lời khi giá giảm; hai thuật ngữ này dùng phổ biến trong giao dịch hợp đồng tương lai và ký quỹ.","body":[["Khi long, bạn mua hoặc mở hợp đồng mua và có lãi nếu giá tăng. Khi short, bạn bán trước bằng hợp đồng hoặc coin đi vay và có lãi nếu giá giảm. Trên ",["giao dịch spot","spot-trading"]," thông thường bạn chỉ long được; để short cần ",["hợp đồng tương lai","futures-contract"],", ký quỹ hoặc sản phẩm phái sinh khác."],["Rủi ro của hai chiều không đối xứng hoàn toàn. Long không ",["đòn bẩy","leverage"]," lỗ tối đa 100% khi giá về 0. Short về lý thuyết lỗ không giới hạn vì giá có thể tăng mãi, dù trong thực tế ",["thanh lý","liquidation"]," sẽ đóng vị thế trước."],"Nhiều sàn có chế độ một chiều (one-way) hoặc hai chiều (hedge mode). Ở chế độ hai chiều, bạn có thể giữ long và short cùng lúc trên một cặp."],"example":["Giả sử ADA ở 0,50 ",["USDT","usdt"],". Bạn long 2.000 ADA và bạn của bạn short 2.000 ADA, cùng giá trị vị thế 1.000 USDT. Nếu ADA lên 0,55, bạn lãi 2.000 × 0,05 = 100 USDT và bạn của bạn lỗ 100 USDT. Nếu ADA xuống 0,44, bạn lỗ 120 USDT còn người short lãi 120 USDT, chưa tính phí và funding."],"mistakes":["Bấm nhầm nút long/short hoặc buy/sell khi đóng vị thế, vô tình mở vị thế ngược.","Nghĩ rằng short an toàn hơn vì thị trường đang giảm.","Không biết tài khoản đang ở chế độ một chiều hay hai chiều."],"faq":[{"q":"Long và short là gì?","a":"Long là kỳ vọng giá tăng, short là kỳ vọng giá giảm. Bạn có thể kiếm lời ở cả hai chiều bằng hợp đồng tương lai."},{"q":"Có thể short trên spot không?","a":"Không trực tiếp. Bạn cần vay coin qua giao dịch ký quỹ, hoặc dùng hợp đồng tương lai để short."}],"title":"Long và short là gì? Vị thế mua bán trong crypto","description":"Long và short là gì, cách kiếm lời khi giá tăng hoặc giảm, khác biệt rủi ro hai chiều và các chế độ vị thế trên sàn.","related":[["short-selling","Bán khống (Short selling)","Bán khống là việc bán một tài sản bạn không sở hữu, bằng cách vay hoặc dùng hợp đồng phái sinh, với kỳ vọng mua lại ở giá thấp hơn để kiếm lời."],["perpetual-futures","Hợp đồng tương lai vĩnh cửu (Perpetual)","Hợp đồng tương lai vĩnh cửu (perpetual) là hợp đồng tương lai không có ngày đáo hạn, dùng cơ chế funding rate để giữ giá hợp đồng bám sát giá spot."],["leverage","Đòn bẩy (Leverage)","Đòn bẩy là việc dùng một khoản ký quỹ nhỏ để mở vị thế có giá trị lớn hơn nhiều lần, làm phóng đại cả lợi nhuận lẫn thua lỗ."],["long-short-ratio","Tỷ lệ Long/Short (Long/short ratio)","Tỷ lệ long/short là chỉ số so sánh số tài khoản hoặc khối lượng vị thế đang long với số đang short trên một sàn, dùng để đọc tâm lý người giao dịch phái sinh."]],"lesson":{"id":"E18","slug":"spot-vs-futures","ep":18,"title":"Giao ngay và tương lai: bạn không mua cùng một thứ"},"coin":null,"tool":null,"cta":true},"short-selling":{"slug":"short-selling","cat":"derivatives","en":"Short selling","contentLocale":"vi","term":"Bán khống (Short selling)","aka":["short selling","bán khống","short","đánh xuống"],"short":"Bán khống là việc bán một tài sản bạn không sở hữu, bằng cách vay hoặc dùng hợp đồng phái sinh, với kỳ vọng mua lại ở giá thấp hơn để kiếm lời.","body":[["Trong crypto có hai cách bán khống phổ biến. Cách thứ nhất là margin spot: vay coin từ sàn, bán ngay, sau đó mua lại để trả nợ và trả lãi vay. Cách thứ hai là short ",["hợp đồng tương lai","futures-contract"],", không cần vay coin thật mà chỉ cần ký quỹ."],["Bán khống dùng để kiếm lời khi giá giảm hoặc để ",["phòng hộ","hedging"]," cho lượng coin đang nắm giữ. Rủi ro lớn là giá tăng: lỗ tăng theo, và khi nhiều người short cùng lúc bị ép đóng vị thế, giá có thể bật tăng mạnh, gọi là ",["short squeeze","short-squeeze"],"."],"Chi phí cũng khác nhau: margin spot trả lãi vay, có thể rất cao với coin khan hiếm; futures trả hoặc nhận funding."],"example":["Giả sử LTC ở 90 ",["USDT","usdt"],". Bạn vay 10 LTC qua margin và bán, nhận 900 USDT. Một tuần sau LTC giảm xuống 80 USDT, bạn mua lại 10 LTC với 800 USDT để trả nợ. Lãi vay giả sử 0,05% mỗi ngày trên 900 USDT, tức khoảng 3,15 USDT sau 7 ngày. Lợi nhuận ròng xấp xỉ 900 - 800 - 3,15 = 96,85 USDT trước phí giao dịch."],"mistakes":["Short coin vốn hóa nhỏ thanh khoản thấp, nơi giá có thể bị đẩy tăng rất nhanh.","Quên lãi vay khi giữ vị thế short margin lâu ngày.","Short chỉ vì giá đã tăng nhiều mà không có cắt lỗ."],"faq":[{"q":"Bán khống crypto như thế nào?","a":"Bạn có thể short hợp đồng tương lai hoặc vay coin qua giao dịch ký quỹ rồi bán. Cả hai đều có lãi khi giá giảm và lỗ khi giá tăng."},{"q":"Bán khống có lỗ không giới hạn không?","a":"Về lý thuyết có, vì giá có thể tăng không giới hạn. Trên sàn, vị thế sẽ bị thanh lý trước khi lỗ vượt quá ký quỹ được dùng."}],"title":"Bán khống (short selling) là gì trong crypto?","description":"Bán khống crypto là gì, cách short qua ký quỹ hoặc hợp đồng tương lai, chi phí lãi vay và rủi ro khi giá tăng.","related":[["long-and-short","Long và Short (Vị thế mua và bán)","Long là mở vị thế kiếm lời khi giá tăng, short là mở vị thế kiếm lời khi giá giảm; hai thuật ngữ này dùng phổ biến trong giao dịch hợp đồng tương lai và ký quỹ."],["perpetual-futures","Hợp đồng tương lai vĩnh cửu (Perpetual)","Hợp đồng tương lai vĩnh cửu (perpetual) là hợp đồng tương lai không có ngày đáo hạn, dùng cơ chế funding rate để giữ giá hợp đồng bám sát giá spot."],["margin-trading","Giao dịch ký quỹ (Margin trading)","Giao dịch ký quỹ là việc vay thêm vốn từ sàn, dùng tài sản của bạn làm tài sản đảm bảo, để mở vị thế lớn hơn số tiền bạn có."],["short-squeeze","Short squeeze (Ép short)","Short squeeze là hiện tượng giá tăng nhanh buộc nhiều người đang short phải đóng vị thế hoặc bị thanh lý, và lệnh mua bắt buộc của họ lại đẩy giá tăng tiếp."]],"lesson":{"id":"E18","slug":"spot-vs-futures","ep":18,"title":"Giao ngay và tương lai: bạn không mua cùng một thứ"},"coin":null,"tool":null,"cta":false},"futures-basis":{"slug":"futures-basis","cat":"derivatives","en":"Futures basis","contentLocale":"vi","term":"Basis hợp đồng tương lai (Futures basis)","aka":["basis","futures basis","chênh lệch basis","premium hợp đồng"],"short":"Basis là chênh lệch giữa giá hợp đồng tương lai và giá spot (hoặc giá chỉ số) của cùng một tài sản, thường được thể hiện bằng số tiền hoặc tỷ lệ phần trăm năm.","body":[["Khi giá hợp đồng cao hơn spot, thị trường ở trạng thái contango và basis dương. Khi thấp hơn, thị trường ở trạng thái backwardation và basis âm. Trong crypto, basis dương phổ biến hơn vì nhu cầu long có ",["đòn bẩy","leverage"]," thường lớn."],["Với hợp đồng giao sau, basis thu hẹp dần về 0 khi gần ngày đáo hạn. Vì vậy người giao dịch thường quy đổi basis ra tỷ lệ năm để so sánh hợp đồng có thời hạn khác nhau. Với ",["hợp đồng vĩnh cửu","perpetual-futures"],", basis được kéo về gần 0 liên tục bằng ",["funding rate","funding-rate"],"."],"Basis là nền tảng của giao dịch cash-and-carry: mua spot và bán hợp đồng để thu phần chênh lệch. Basis có thể nới rộng tạm thời trước khi hội tụ, nên vị thế cần đủ ký quỹ."],"example":["Giả sử ",["BTC","bitcoin"]," spot ở 64.000 ",["USDT","usdt"]," và hợp đồng đáo hạn sau 120 ngày ở 65.600 USDT. Basis là 1.600 USDT, tức 2,5%. Quy đổi ra năm: 2,5% × 365 / 120 ≈ 7,6% mỗi năm. Nếu một hợp đồng khác đáo hạn sau 30 ngày có basis 1%, tỷ lệ năm là khoảng 12,2%, cao hơn dù con số tuyệt đối nhỏ hơn."],"mistakes":["So sánh basis của các hợp đồng có thời hạn khác nhau mà không quy đổi ra tỷ lệ năm.","Nghĩ rằng basis dương nghĩa là giá spot sẽ tăng lên bằng giá hợp đồng.","Bỏ qua việc basis có thể nới rộng trước khi hội tụ."],"faq":[{"q":"Basis trong futures là gì?","a":"Là chênh lệch giữa giá hợp đồng tương lai và giá spot. Basis dương gọi là contango, âm gọi là backwardation."},{"q":"Basis có dự báo giá không?","a":"Không. Basis phản ánh nhu cầu đòn bẩy và chi phí vốn, không cho biết giá spot sẽ đi về đâu."}],"title":"Basis là gì? Chênh lệch giá futures và spot","description":"Basis hợp đồng tương lai là gì, contango và backwardation khác nhau thế nào và cách quy đổi basis ra tỷ lệ năm.","related":[["delivery-futures","Hợp đồng tương lai giao sau (Delivery futures)","Hợp đồng tương lai giao sau là hợp đồng có ngày đáo hạn cố định, ví dụ theo tuần hoặc theo quý, và được tất toán theo giá chỉ số vào thời điểm đáo hạn."],["funding-rate","Funding rate (Tỷ lệ funding)","Funding rate là khoản thanh toán định kỳ giữa phe long và phe short trong hợp đồng tương lai vĩnh cửu, giúp giá hợp đồng bám sát giá spot."],["index-price","Giá chỉ số (Index price)","Giá chỉ số (index price) là giá trung bình có trọng số của một tài sản trên nhiều sàn spot lớn, được dùng làm tham chiếu cho giá đánh dấu và funding rate."],["funding-rate-arbitrage","Arbitrage funding rate (Kinh doanh chênh lệch funding)","Arbitrage funding rate là chiến lược giữ vị thế trung lập về giá, thường là mua spot và short perpetual cùng lượng, để thu khoản funding được trả định kỳ."]],"lesson":null,"coin":null,"tool":"/funding-rates","cta":false},"blockchain-network":{"slug":"blockchain-network","cat":"wallets-security","en":"Deposit network (chain selection)","contentLocale":"vi","term":"Mạng nạp rút (Chọn mạng blockchain)","aka":["mạng lưới","network","chọn mạng","chain"],"short":"Mạng nạp rút là blockchain cụ thể mà một đồng coin được chuyển qua, ví dụ USDT có thể đi trên Tron (TRC20), Ethereum (ERC20) hay BNB Chain (BEP20); bên gửi và bên nhận phải dùng cùng mạng.","body":[["Nhiều token tồn tại trên nhiều ",["blockchain","blockchain"]," cùng lúc. ",["USDT","usdt"]," trên Tron và USDT trên ",["Ethereum","ethereum"]," đều là USDT, nhưng chúng sống trên hai sổ cái khác nhau và không tự đi qua lại được. Khi rút tiền, sàn hỏi bạn chọn mạng nào; ví hoặc sàn nhận phải hỗ trợ đúng mạng đó."],["Mỗi mạng có phí và tốc độ khác nhau. Ethereum thường đắt hơn khi mạng bận, còn Tron, BNB Chain, Solana hay các ",["layer 2","layer-2"]," thường rẻ hơn. Sàn cũng đặt ",["phí rút","withdrawal-fee"]," riêng cho từng mạng, nên hãy so sánh trước khi chọn."],"Gửi sai mạng là lỗi phổ biến nhất của người mới. Đôi khi sàn có thể khôi phục với phí xử lý, đôi khi tiền mất hẳn, tùy loại địa chỉ và chính sách của sàn."],"example":"Giả sử bạn chuyển 1.000 USDT từ sàn A sang sàn B. Trang nạp của sàn B hỗ trợ TRC20 và ERC20. Sàn A báo phí rút ví dụ 1 USDT qua TRC20 và 5 USDT qua ERC20. Bạn chọn TRC20 ở cả hai phía, nhận về 999 USDT. Nếu chọn ERC20, bạn nhận 995 USDT. Nếu chọn BEP20 trong khi sàn B không hỗ trợ BEP20, khoản tiền có thể bị kẹt.","mistakes":["Chỉ khớp địa chỉ mà không khớp mạng ở bên gửi và bên nhận.","Chọn mạng chỉ vì phí rẻ nhất mà không kiểm tra ví nhận có hỗ trợ mạng đó không.","Nghĩ rằng địa chỉ 0x trên Ethereum và BNB Chain dùng được thay thế nhau ở mọi sàn."],"faq":[{"q":"TRC20 và ERC20 khác nhau thế nào?","a":"TRC20 là chuẩn token trên Tron, ERC20 là chuẩn token trên Ethereum. Cùng là USDT nhưng nằm trên hai blockchain khác nhau, phí và tốc độ cũng khác."},{"q":"Chuyển sai mạng thì phải làm sao?","a":"Liên hệ ngay bộ phận hỗ trợ của sàn hoặc ví nhận, kèm mã giao dịch. Khả năng lấy lại phụ thuộc vào việc bên nhận có kiểm soát địa chỉ đó trên mạng bạn đã gửi hay không."}],"title":"Chọn mạng nạp rút là gì? TRC20, ERC20, BEP20","description":"Mạng nạp rút crypto là gì, khác nhau giữa TRC20, ERC20, BEP20, cách chọn đúng mạng và tránh mất tiền khi chuyển sai.","related":[["wallet-address","Địa chỉ ví (Wallet address)","Địa chỉ ví là chuỗi ký tự công khai đại diện cho nơi nhận crypto trên một blockchain cụ thể, giống số tài khoản ngân hàng nhưng gắn với từng mạng lưới."],["memo-tag","Memo / Tag (Destination tag)","Memo hay tag là mã bổ sung đi kèm địa chỉ ví trên một số blockchain như XRP, XLM, TON, ATOM, giúp sàn biết khoản nạp vào địa chỉ chung thuộc về tài khoản nào."],["gas-fee","Phí gas (Gas fee)","Phí gas là khoản phí bạn trả cho mạng blockchain để xử lý một giao dịch hoặc thao tác với hợp đồng thông minh, tính bằng coin gốc của mạng như ETH trên Ethereum."],["withdrawal-fee","Phí rút tiền (withdrawal fee)","Phí rút tiền là khoản phí sàn thu khi bạn chuyển crypto từ tài khoản sàn ra ví hoặc sàn khác, thường là một số coin cố định tùy theo mạng blockchain bạn chọn."],["transaction-hash","Mã giao dịch (Transaction hash, TxID)","Mã giao dịch (TxID hay TxHash) là chuỗi ký tự duy nhất định danh một giao dịch trên blockchain, dùng để tra cứu trạng thái, số tiền, phí và số xác nhận của giao dịch đó."]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"Trước khi chuyển coin: Tuyệt đối không đoán mò những điểm này"},"coin":null,"tool":null,"cta":false},"mempool":{"slug":"mempool","cat":"onchain","en":"Mempool","contentLocale":"vi","term":"Mempool (vùng chờ giao dịch)","aka":["mempool","memory pool","hàng chờ giao dịch"],"short":"Mempool là nơi các giao dịch đã được phát lên mạng nhưng chưa được đưa vào khối nằm chờ, trước khi thợ đào hoặc validator chọn để xác nhận.","body":[["Khi bạn gửi ",["BTC","bitcoin"]," hoặc ",["ETH","ethereum"],", giao dịch không vào ",["blockchain","blockchain"]," ngay. Nó được chuyển tới các ",["node","node"]," và nằm trong mempool. Mỗi node có mempool riêng, nên nội dung giữa các node có thể khác nhau đôi chút."],["Không gian trong mỗi khối có hạn, nên thợ đào hoặc ",["validator","validator"]," thường ưu tiên giao dịch trả phí cao hơn. Khi mempool đông, phí tăng và giao dịch phí thấp có thể bị kẹt hàng giờ, thậm chí bị loại khỏi mempool sau một thời gian."],["Mempool cũng là nơi diễn ra ",["MEV","mev"],": bot quan sát giao dịch đang chờ, ví dụ một lệnh swap lớn trên DEX, rồi chen giao dịch của mình vào trước hoặc sau để kiếm lời. Đây là lý do nhiều ví cung cấp tùy chọn gửi giao dịch qua kênh riêng tư."]],"example":"Giả sử mempool Bitcoin đang đông, giao dịch được xác nhận nhanh trả khoảng 40 sat/vByte. Giao dịch của bạn nặng 140 vByte nhưng chỉ đặt 8 sat/vByte, tức phí 1.120 sat. Nó có thể nằm chờ nhiều giờ. Nếu ví hỗ trợ Replace-By-Fee, bạn nâng phí lên 40 sat/vByte, tức 5.600 sat, khoảng 0,000056 BTC, và giao dịch thường được đưa vào một trong vài khối tiếp theo.","mistakes":["Gửi lại giao dịch lần nữa khi lần đầu đang kẹt, dẫn tới rủi ro trả hai lần nếu cả hai cùng được xác nhận.","Đặt phí thấp nhất có thể vào lúc mạng đang tắc nghẽn.","Tưởng giao dịch đang chờ trong mempool là đã hoàn tất."],"faq":[{"q":"Giao dịch kẹt trong mempool có bị mất tiền không?","a":"Thường là không. Nếu không được xác nhận, giao dịch có thể bị loại khỏi mempool và tiền vẫn ở ví gốc, hoặc bạn có thể tăng phí nếu ví hỗ trợ."},{"q":"Ethereum có mempool không?","a":"Có. Ethereum cũng có giao dịch chờ, và mức ưu tiên phụ thuộc vào phí ưu tiên bạn đặt. Ví hỗ trợ tăng tốc hoặc hủy bằng cách gửi giao dịch cùng nonce với phí cao hơn."}],"title":"Mempool là gì? Vì sao giao dịch crypto bị kẹt","description":"Mempool là vùng chờ của giao dịch chưa xác nhận. Tìm hiểu vì sao giao dịch bị kẹt, cách tính phí và cách tăng tốc.","related":[["gas-fee","Phí gas (Gas fee)","Phí gas là khoản phí bạn trả cho mạng blockchain để xử lý một giao dịch hoặc thao tác với hợp đồng thông minh, tính bằng coin gốc của mạng như ETH trên Ethereum."],["transaction-hash","Mã giao dịch (Transaction hash, TxID)","Mã giao dịch (TxID hay TxHash) là chuỗi ký tự duy nhất định danh một giao dịch trên blockchain, dùng để tra cứu trạng thái, số tiền, phí và số xác nhận của giao dịch đó."],["mev","MEV (Giá trị khai thác tối đa)","MEV là phần lợi nhuận mà người sắp xếp giao dịch trong khối, như validator hay bot tìm kiếm, có thể thu được bằng cách chèn, sắp xếp lại hoặc loại bỏ giao dịch."],["block-confirmations","Số xác nhận khối (Block confirmations)","Số xác nhận khối là số khối đã được thêm vào blockchain kể từ khối chứa giao dịch của bạn; càng nhiều xác nhận thì giao dịch càng khó bị đảo ngược."]],"lesson":{"id":"E10","slug":"transfer-not-arrived","ep":10,"title":"Báo đã gửi nhưng tiền chưa tới. Cần kiểm tra ở đâu?"},"coin":null,"tool":null,"cta":false},"no-kyc-exchange":{"slug":"no-kyc-exchange","cat":"regulation","en":"No-KYC exchange","contentLocale":"vi","term":"Sàn không KYC","aka":["sàn no KYC","no-KYC exchange","sàn không xác minh danh tính"],"short":"Sàn không KYC là nơi cho phép giao dịch hoặc rút crypto mà không cần xác minh danh tính, thường trong một hạn mức nhất định hoặc thông qua mô hình phi tập trung.","body":[["Có hai nhóm chính. Nhóm thứ nhất là ",["sàn phi tập trung","dex"]," như Uniswap hay các ",["perp DEX","perp-dex"]," như Hyperliquid, nơi bạn giao dịch trực tiếp từ ví mà không mở tài khoản. Nhóm thứ hai là ",["sàn tập trung","centralized-exchange"]," cho phép rút một hạn mức nhỏ mỗi ngày trước khi yêu cầu ",["KYC","kyc"],"."],"Ưu điểm là riêng tư và mở tài khoản nhanh. Đổi lại, bạn có ít sự bảo vệ hơn: sàn tập trung không KYC có thể bất ngờ yêu cầu xác minh khi bạn muốn rút số tiền lớn, và nếu bị khóa, bạn khó chứng minh mình là chủ tài khoản.",["Sàn không KYC cũng thường bị hạn chế khu vực và có thể bị các cơ quan quản lý cảnh báo. Không KYC không có nghĩa là ẩn danh tuyệt đối, vì giao dịch trên ",["blockchain","blockchain"]," vẫn công khai và có thể được truy vết."]],"example":["Giả sử một sàn tập trung cho tài khoản chưa KYC rút tối đa tương đương 2 ",["BTC","bitcoin"]," mỗi ngày. Bạn nạp 8.000 USDT, giao dịch lời và số dư lên 12.000 USDT. Khi rút toàn bộ, hệ thống yêu cầu KYC vì giao dịch của bạn bị đánh dấu để xem xét. Nếu bạn ở khu vực sàn không phục vụ, bạn có thể không hoàn tất KYC được và tiền bị giữ. Hạn mức trên chỉ là minh họa, mỗi sàn có quy định riêng."],"mistakes":["Gửi số tiền lớn lên sàn tập trung không KYC rồi mới phát hiện hạn mức rút.","Tin rằng sàn không KYC giúp giao dịch hoàn toàn ẩn danh.","Bỏ qua điều khoản về khu vực bị hạn chế của sàn."],"faq":[{"q":"DEX có cần KYC không?","a":"Phần lớn DEX chỉ cần kết nối ví, không cần KYC. Tuy nhiên giao diện web của một số DEX có thể chặn người dùng từ những khu vực nhất định."},{"q":"Sàn không KYC có hợp pháp không?","a":"Tùy luật từng quốc gia. Nhiều nơi yêu cầu sàn tập trung phải KYC, nên sàn không KYC có thể hoạt động ngoài khung cấp phép ở khu vực đó."}],"title":"Sàn không KYC là gì? Ưu nhược điểm cần biết","description":"Sàn không KYC cho giao dịch không cần xác minh danh tính. Hiểu DEX, hạn mức rút, rủi ro bị giữ tiền và giới hạn khu vực.","related":[["kyc","KYC (xác minh danh tính khách hàng)","KYC là quy trình sàn giao dịch hoặc tổ chức tài chính xác minh danh tính người dùng bằng giấy tờ tùy thân, ảnh khuôn mặt và đôi khi là địa chỉ cư trú."],["dex","Sàn phi tập trung (DEX)","Sàn phi tập trung (DEX) là nơi giao dịch crypto trực tiếp từ ví của bạn qua hợp đồng thông minh, không cần nạp tiền vào tài khoản của một công ty trung gian."],["withdrawal-fee","Phí rút tiền (withdrawal fee)","Phí rút tiền là khoản phí sàn thu khi bạn chuyển crypto từ tài khoản sàn ra ví hoặc sàn khác, thường là một số coin cố định tùy theo mạng blockchain bạn chọn."],["centralized-exchange","Sàn giao dịch tập trung (CEX)","Sàn giao dịch tập trung (CEX) là nền tảng do một công ty vận hành, giữ tài sản của người dùng và khớp lệnh mua bán trên sổ lệnh nội bộ, như Binance, OKX, Bybit hay Bitget."]],"lesson":{"id":"E05","slug":"kyc-who-gets-your-id","ep":5,"title":"KYC thực hiện như thế nào và ai mới là người nhận giấy tờ của bạn?"},"coin":null,"tool":"/topics/no-kyc","cta":false},"fiat-on-ramp":{"slug":"fiat-on-ramp","cat":"regulation","en":"Fiat on-ramp","contentLocale":"vi","term":"Cổng nạp tiền pháp định (fiat on-ramp)","aka":["fiat on-ramp","on-ramp","nạp fiat","cổng mua crypto"],"short":"Cổng nạp tiền pháp định là dịch vụ cho phép bạn đổi tiền như VND hay USD thành crypto, qua chuyển khoản ngân hàng, thẻ, ví điện tử hoặc giao dịch P2P.","body":[["Đây là bước đầu tiên của hầu hết người mới: đưa tiền từ hệ thống ngân hàng vào thế giới crypto. Các cách phổ biến gồm mua bằng thẻ Visa hoặc Mastercard trên sàn, chuyển khoản ngân hàng nếu sàn hỗ trợ đồng tiền đó, dùng đối tác thanh toán bên thứ ba, hoặc mua ",["USDT","usdt"]," qua ",["chợ P2P","p2p-trading"],"."],"Mỗi kênh khác nhau về phí, tốc độ, hạn mức và mức độ an toàn. Thẻ nhanh nhưng phí thường cao hơn. P2P thường có giá sát thị trường nhưng cần cẩn thận với người bán và nguồn tiền. Chiều ngược lại, đổi crypto về tiền pháp định, được gọi là off-ramp.",["Hầu hết cổng nạp đều yêu cầu ",["KYC","kyc"],". Hãy so sánh tổng chi phí thực tế, gồm phí, tỷ giá và chênh lệch, thay vì chỉ nhìn dòng phí quảng cáo."]],"example":"Giả sử bạn muốn mua 500 USDT. Qua thẻ, sàn báo phí 2% và tỷ giá 25.600 đồng mỗi USDT, tổng chi khoảng 12,8 triệu cộng 256.000 đồng phí, gần 13,06 triệu đồng. Qua P2P, người bán chào 25.750 đồng mỗi USDT và không phí, tổng 12,875 triệu đồng. Trong ví dụ này P2P rẻ hơn khoảng 180.000 đồng, nhưng bạn cần kiểm tra uy tín người bán. Các con số chỉ minh họa.","mistakes":["Chỉ nhìn phí giao dịch mà bỏ qua tỷ giá quy đổi bị cộng thêm.","Chọn người bán P2P giá rẻ bất thường mà không xem lịch sử giao dịch.","Mua crypto qua đường link lạ thay vì ứng dụng chính thức của sàn."],"faq":[{"q":"Cách rẻ nhất để mua USDT bằng VND là gì?","a":"Tùy thời điểm và sàn. Hãy so sánh tổng số đồng phải trả cho cùng một lượng USDT qua thẻ, P2P và các đối tác thanh toán trước khi chọn."},{"q":"On-ramp và off-ramp khác nhau thế nào?","a":"On-ramp là đổi tiền pháp định thành crypto. Off-ramp là chiều ngược lại, bán crypto để nhận tiền pháp định về ngân hàng."}],"title":"Fiat on-ramp là gì? Cách đổi VND sang crypto","description":"Fiat on-ramp là kênh đổi tiền pháp định sang crypto. So sánh thẻ, chuyển khoản và P2P về phí, tỷ giá và mức độ an toàn.","related":[["p2p-trading","Giao dịch P2P (C2C)","Giao dịch P2P là hình thức mua bán crypto trực tiếp giữa hai người dùng trên một nền tảng, trong đó sàn giữ coin của người bán làm bảo đảm cho tới khi người mua thanh toán xong."],["kyc","KYC (xác minh danh tính khách hàng)","KYC là quy trình sàn giao dịch hoặc tổ chức tài chính xác minh danh tính người dùng bằng giấy tờ tùy thân, ảnh khuôn mặt và đôi khi là địa chỉ cư trú."],["centralized-exchange","Sàn giao dịch tập trung (CEX)","Sàn giao dịch tập trung (CEX) là nền tảng do một công ty vận hành, giữ tài sản của người dùng và khớp lệnh mua bán trên sổ lệnh nội bộ, như Binance, OKX, Bybit hay Bitget."],["stablecoin","Stablecoin (Đồng tiền ổn định)","Stablecoin là đồng crypto được thiết kế để giữ giá ổn định so với một tài sản tham chiếu, phổ biến nhất là 1 USD, như USDT và USDC."]],"lesson":{"id":"E06","slug":"first-deposit-paths","ep":6,"title":"Lần nạp tiền đầu tiên: Tiền đến từ đâu và đi về đâu?"},"coin":null,"tool":null,"cta":true}});
